#!/usr/bin/env python3
"""
Simple jinja2 template renderer as a replacement for the unmaintained j2cli tool.
"""

import sys
import os
import argparse
import json
from pathlib import Path
from jinja2 import Environment, FileSystemLoader, StrictUndefined, select_autoescape
import jinja2.filters
import subprocess
import yaml

# Jinja-exported functions and filters

def shell(command):
    # We remove trailing spaces as they are often generated by shell code for interactive use, but not wanted here.
    return subprocess.check_output(command, shell=True, stdin=None, stderr=subprocess.STDOUT, text=True).rstrip()

def to_yaml(value):
    class LiteralDumper(yaml.SafeDumper):
        """Custom yaml dumper that dumps multi-line strings as literals"""
        pass

    def str_presenter(dumper, data):
        style = "|" if "\n" in data else None
        return dumper.represent_scalar("tag:yaml.org,2002:str", data, style=style)

    LiteralDumper.add_representer(str, str_presenter)

    return yaml.dump(value, default_flow_style=False, sort_keys=False, Dumper=LiteralDumper).rstrip()

def nindent(value, width):
    prefix = width * " "
    return "\n" + "\n".join(prefix + line for line in value.splitlines())

# Functions for the actual functionality

def load_data(data_file):
    path = Path(data_file)
    content = path.read_text()
    return yaml.safe_load(content)

def make_engine(input: Path):
    env = Environment(
        undefined=StrictUndefined,
        autoescape=select_autoescape(),
        trim_blocks=True,
        lstrip_blocks=True,
        loader=FileSystemLoader(input.parent)
    )
    env.filters.update(jinja2.filters.FILTERS)
    env.filters["to_yaml"] = to_yaml
    env.filters["nindent"] = nindent
    env.globals["env"] = dict(os.environ)
    env.globals["shell"] = shell
    return env

def main():
    parser = argparse.ArgumentParser(description='Simple jinja2 template renderer as a replacement for the unmaintained j2cli tool')

    parser.add_argument('template', help='Template file (use - for stdin)')
    parser.add_argument('data', nargs='?', help='Json file for context values')
    parser.add_argument('--insecure', action='store_true', help='Generate the compose file for an insecure deployment')

    args = parser.parse_args()

    path = Path("/dev/stdin" if args.template == "-" else args.template)
    template = make_engine(path).get_template(path.name)
    data = load_data(args.data)
    
    data["atls"] = not args.insecure

    # Render template
    try:
        result = template.render(data)
    except Exception as e:
        print(f"Error rendering template: {e}", file=sys.stderr)
        sys.exit(1)

    print(result, end='')


if __name__ == '__main__':
    main()
